{"sections": [
  {"id": "s1", "section": "landscape", "text": "Eight trials test FcRn inhibitors in CIDP, including two Phase 2 trials that terminated for sponsor decision and two currently running Phase 2 studies.", "cites": ["NCT05581199", "NCT07032662", "NCT04280718"]},
  {"id": "s2", "section": "landscape", "text": "Sponsors include Immunovant, argenx and UCB, with argenx and Immunovant each running multiple trials and argenx having completed two Phase 2 studies.", "cites": ["NCT04280718", "NCT03861481"]},
  {"id": "s3", "section": "track_record", "text": "Efgartigimod alfa is approved for CIDP in the U.S. as a subcutaneous formulation in combination with hyaluronidase.", "cites": ["FDA:7104d9e5-9910-47f5-9a93-741ac50f43b6"]},
  {"id": "s4", "section": "track_record", "text": "Two trials of batoclimab in CIDP were terminated due to sponsor decision, with no safety concerns cited.", "cites": ["NCT05581199", "NCT07188844"]},
  {"id": "s5", "section": "literature", "text": "A 2026 review highlights FcRn inhibitors as transformative in CIDP therapy, noting their role in accelerating IgG autoantibody degradation.", "cites": ["PMID:42749655"]},
  {"id": "s6", "section": "literature", "text": "A 2026 network meta-analysis found FcRn inhibitors effective in CIDP with favorable safety and functional outcomes compared to conventional therapies.", "cites": ["PMID:42807841"]},
  {"id": "s7", "section": "competition", "text": "FcRn inhibitors compete with IVIg, corticosteroids and plasma exchange, with efgartigimod offering targeted IgG reduction and subcutaneous administration.", "cites": ["PMID:42921078", "FDA:7104d9e5-9910-47f5-9a93-741ac50f43b6"]},
  {"id": "s8", "section": "competition", "text": "The site's stop-risk estimate for FcRn in CIDP is unavailable.", "cites": ["RISK:fcrn:CIDP"]}
], "read": ["Mechanism evidence: FcRn inhibition shows strong efficacy in reducing pathogenic IgG in CIDP, supported by approval and meta-analyses.", "Competitive position: Approved subcutaneous option available; distinct from IVIg but targets same pathway.", "Open questions: Long-term safety and comparative effectiveness against IVIg remain under study."], "judgement": {"stance": "favours", "confidence": "high", "reasons": ["s3", "s6", "s7"]}, "would_change": ["New safety signals from ongoing trials would alter the risk profile.", "Evidence of inferior functional outcomes compared to IVIg would weaken the position."]}

